using Celsius = double;
using Fahrenheit = double;

Celsius toCelsius(Fahrenheit f)
{
    return (f - 32.0) * 5.0 / 9.0;
}

unitTests:
static_assert(std::is_same_v<Celsius, double>, "Celsius should be an alias for double");
static_assert(std::is_same_v<Fahrenheit, double>, "Fahrenheit should be an alias for double");

TEST("freezing and boiling") { CHECK_NEAR(toCelsius(32.0), 0.0, 1e-9); CHECK_NEAR(toCelsius(212.0), 100.0, 1e-9); }
TEST("body temperature") { CHECK_NEAR(toCelsius(98.6), 37.0, 1e-9); }

